values ('bbbb0004-0000-4000-8000-000000000009', 'en', null, 'U.S. History', 'A chronological survey of the United States — from colonial settlement and the Revolution through the Constitution, the Civil War, industrialization, and the twentieth century. Structure adapted from OpenStax U.S. History (CC BY 4.0).', null, 'foundations', 9, true, 'science', '{}')
